        expected: {
          path: "/a-b-c",
          params: { foo: ["a"], bar: "b", baz: ["c"] },
        },
      },
      {
        input: "/a-b-c-d",
        expected: {
          path: "/a-b-c-d",
          params: { foo: ["a-b"], bar: "c", baz: ["d"] },
        },
      },
    ],
  },
  {
