import { parse, stringify } from "../src/index.js";

// Test cases from STRINGIFY_TESTS in cases.spec.ts
// These test that stringify correctly quotes param names followed by astral ID_Continue chars

const testCases = [
  {
    name: "Param followed by astral ID_Continue (U+1D6FC)",
    tokens: [
      { type: "text" as const, value: "/" },
      { type: "param" as const, name: "test" },
      { type: "text" as const, value: "\u{1D6FC}" },
    ],
    expected: '/:"test"\u{1D6FC}',
  },
  {
    name: "Wildcard followed by astral ID_Continue (U+1D6FC)",
    tokens: [
      { type: "text" as const, value: "/" },
      { type: "wildcard" as const, name: "test" },
      { type: "text" as const, value: "\u{1D6FC}" },
    ],
    expected: '/*"test"\u{1D6FC}',
  },
  {
    name: "Param followed by non-ID_Continue astral (U+1F600)",
    tokens: [
      { type: "text" as const, value: "/" },
      { type: "param" as const, name: "test" },
      { type: "text" as const, value: "\u{1F600}" },
    ],
    expected: "/:test\u{1F600}",
  },
];

console.log("Testing parse/stringify round-trip for astral characters");
console.log("=".repeat(60));

let allPassed = true;

for (const tc of testCases) {
  const data = {
    tokens: tc.tokens,
    originalPath: undefined as string | undefined,
  };

  const result = stringify(data);
  const passed = result === tc.expected;

  console.log(`\nTest: ${tc.name}`);
  console.log(`  Expected: ${JSON.stringify(tc.expected)}`);
  console.log(`  Got:      ${JSON.stringify(result)}`);
  console.log(`  Passed:   ${passed}`);

  if (!passed) {
    allPassed = false;
    console.log("  ❌ FAILED");
  } else {
    console.log("  ✓ PASSED");
  }
}

console.log("\n" + "=".repeat(60));
console.log(allPassed ? "All tests passed!" : "Some tests FAILED!");
process.exit(allPassed ? 0 : 1);

